(async () => {

    const WORLD_BOOK_NAME = "合欢宗扩展";

    const CONTROL_ENTRIES = [
        "百花谷设定补充【开始】",
        "百花谷设定补充【结束】",
        "设施-芳华集",
        "设施-流芳津",
        "设施-烟霞街",
        "设施-迎春馆",
        "设施-流觞苑",
        "设施-霓裳台",
        "设施-镜花园",
        "设施-流霞台",
        "设施-照影间",
        "设施-流香院",
        "设施-听雨居",
        "设施-玉露泉",
        "设施-锁心堂",
        "设施-摘星楼",
        "设施-欲湖",
        "身体改造",
        "设施-沉香窟",
        "基础改造",
        "进阶改造",
        "极乐改造",
        "合欢改造",
        "百花谷角色群体设定",
        "道具",
        "百花谷任务发布",
        "百花谷物价参考",
        "设施-绮梦阁",
        "位置信息",
        "特殊活动"
    ];

    // 防止重复启动多个轮询
    if (window.__baiHuaHelperTimer) {
        clearInterval(window.__baiHuaHelperTimer);
        window.__baiHuaHelperTimer = null;
    }

    let lastPlace = null;
    let lastEnable = null;
    let running = false;

    async function runBaiHuaHelper(force = false) {
        if (running) return;
        running = true;

        try {
            const vars = await TavernHelper.getVariables();

            const place = String(
                vars?.stat_data?.世界?.当前地点 || ""
            );

            // 在百花谷：开启；不在百花谷：关闭
            const enable = place.includes("百花谷");

            // 地点没变化就不重复写世界书
            if (!force && place === lastPlace && enable === lastEnable) {
                return;
            }

            lastPlace = place;
            lastEnable = enable;

            console.log(
                "[百花谷控制] 当前地点:",
                place || "(空)",
                "=>",
                enable ? "开启" : "关闭"
            );

            const worldbook =
                await TavernHelper.getWorldbook(WORLD_BOOK_NAME);

            if (!worldbook) {
                console.error(
                    "[百花谷控制] 找不到世界书:",
                    WORLD_BOOK_NAME
                );
                return;
            }

            let changed = 0;

            await TavernHelper.updateWorldbookWith(
                WORLD_BOOK_NAME,
                entries => entries.map(entry => {
                    const name = entry.name || "";

                    if (!CONTROL_ENTRIES.includes(name)) {
                        return entry;
                    }

                    if (entry.enabled !== enable) {
                        changed++;
                        console.log(
                            "[百花谷控制]",
                            name,
                            enable ? "开启" : "关闭"
                        );
                    }

                    return {
                        ...entry,
                        enabled: enable
                    };
                })
            );

            console.log(
                "[百花谷控制] 完成，修改:",
                changed
            );

        } catch (e) {
            console.error("[百花谷控制] 错误:", e);
        } finally {
            running = false;
        }
    }

    window.runBaiHuaHelper = runBaiHuaHelper;

    // 启动时立即执行
    await runBaiHuaHelper(true);

    // 自动监控地点变化；离开百花谷后自动关闭
    window.__baiHuaHelperTimer = setInterval(() => {
        runBaiHuaHelper(false);
    }, 1000);

    console.log(
        "[百花谷控制] 自动监控已启动：每1秒检查一次当前地点"
    );

})();
